CREATE OR REPLACE FUNCTION public.create_validated_financial_program_request_v1_engine(p_actor_real_auth_user_id uuid, p_affiliate_id uuid, p_impersonation_session_id uuid, p_program_item_id uuid, p_notes text, p_signature_data text, p_terms_version_id uuid, p_document_ids uuid[], p_idempotency_key uuid, p_amount numeric, p_term integer, p_term_semantics text, p_expected_profile_version integer, p_financial_submission_snapshot jsonb)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_item public.program_catalog_items%rowtype;
  v_ctx public.impersonation_sessions%rowtype;
  v_row public.program_requests%rowtype;
  v_missing integer;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_actor_real_auth_user_id is null or not exists(select 1 from auth.users where id=p_actor_real_auth_user_id) then
    raise exception 'AUTH_ACTOR_REQUIRED' using errcode='42501';
  end if;
  select * into v_affiliate from public.affiliates where id=p_affiliate_id for update;
  if v_affiliate.id is null or v_affiliate.financial_profile_version<>p_expected_profile_version then
    raise exception 'CONDITIONS_CHANGED' using errcode='PT409';
  end if;
  if p_impersonation_session_id is null then
    if v_affiliate.auth_user_id is distinct from p_actor_real_auth_user_id then raise exception 'AFFILIATE_CONTEXT_DENIED' using errcode='42501'; end if;
  else
    select * into v_ctx from public.impersonation_sessions where id=p_impersonation_session_id for share;
    if v_ctx.id is null or v_ctx.actor_real_auth_user_id<>p_actor_real_auth_user_id
       or v_ctx.usuario_contexto_affiliate_id<>p_affiliate_id or v_ctx.ended_at is not null or v_ctx.expires_at<=now()
       or not exists(select 1 from public.admin_assignments a join public.admin_roles r on r.id=a.role_id and r.enabled where a.auth_user_id=p_actor_real_auth_user_id and a.enabled) then
      raise exception 'IMPERSONATION_CONTEXT_INVALID' using errcode='42501';
    end if;
  end if;
  select * into v_item from public.program_catalog_items
   where id=p_program_item_id and program_key='prestamo' and enabled and request_mode='supabase' and legacy_boundary;
  if v_item.id is null then raise exception 'PROGRAM_NOT_REQUESTABLE' using errcode='22023'; end if;
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_signature_data,'')),'') is null then raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023'; end if;
  if p_amount is null or p_amount<=0 or p_term is null or p_term<=0 or length(btrim(coalesce(p_term_semantics,''))) not between 3 and 80 then
    raise exception 'FINANCIAL_REQUEST_TERMS_INVALID' using errcode='22023';
  end if;
  if not exists(select 1 from public.program_terms_versions where id=p_terms_version_id and program_id='prestamo' and membership_offering_id is null and published) then
    raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023';
  end if;
  if p_financial_submission_snapshot is null
     or jsonb_typeof(p_financial_submission_snapshot)<>'object'
     or not(p_financial_submission_snapshot ?& array[
       'affiliate_id','actor_real_auth_user_id','profile_version','profile_fingerprint',
       'criteria_source_fingerprint','term_policy_fingerprint','calculation_contract_version',
       'criterion_identity','financialResult','confirmed_at'
     ])
     or jsonb_typeof(p_financial_submission_snapshot->'financialResult')<>'object'
     or p_financial_submission_snapshot->>'affiliate_id'<>p_affiliate_id::text
     or p_financial_submission_snapshot->>'actor_real_auth_user_id'<>p_actor_real_auth_user_id::text
     or coalesce(p_financial_submission_snapshot->>'impersonation_session_id','')<>coalesce(p_impersonation_session_id::text,'')
     or (p_financial_submission_snapshot->>'profile_version')::integer<>p_expected_profile_version
     or (p_financial_submission_snapshot->'financialResult'->>'amount')::numeric<>p_amount
     or (p_financial_submission_snapshot->'financialResult'->>'paymentCount')::integer<>p_term then
    raise exception 'FINANCIAL_SUBMISSION_CONTRACT_MISMATCH' using errcode='22023';
  end if;
  select count(*) into v_missing from public.resolve_affiliate_document_requirements('PROGRAM','prestamo',p_affiliate_id) r
   where r.required and not exists(
     select 1 from public.affiliate_documents d where d.id=any(coalesce(p_document_ids,array[]::uuid[]))
       and d.affiliate_id=p_affiliate_id and d.document_type_id=r.document_type_id
       and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED'));
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;

  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_id<>'prestamo'
       or v_row.program_item_id<>p_program_item_id or v_row.requested_amount<>p_amount or v_row.requested_term<>p_term then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;

  insert into public.program_requests(
    actor_real_auth_user_id,affiliate_id,usuario_contexto_affiliate_id,impersonation_session_id,impersonation_reason,
    numero_control,program_id,program_item_id,request_type,status,quantity,notes,signature_data,terms_accepted,
    terms_version_id,source_context,financial_processing_status,idempotency_key,requested_amount,requested_term,
    requested_term_semantics,financial_submission_snapshot
  ) values(
    p_actor_real_auth_user_id,p_affiliate_id,case when v_ctx.id is null then null else p_affiliate_id end,v_ctx.id,v_ctx.reason,
    v_affiliate.numero_control,'prestamo',v_item.id,'quote','requires_financial_processing',1,
    left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,p_terms_version_id,
    jsonb_build_object('source','sutiapp','financial_confirmation','GOOGLE_REVALIDATED','assisted',v_ctx.id is not null),
    'pending',p_idempotency_key,p_amount,p_term,btrim(p_term_semantics),p_financial_submission_snapshot
  ) returning * into v_row;

  insert into public.request_documents(request_id,document_type_id,affiliate_document_id,private_asset_id,asset_sha256,status_at_submission)
  select v_row.id,d.document_type_id,d.id,coalesce(d.private_asset_id,af.private_asset_id),pa.content_sha256,d.status
  from public.affiliate_documents d left join public.affiliate_files af on af.id=d.affiliate_file_id
  join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id)
  where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
    and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
  on conflict(request_id,document_type_id) do nothing;
  return v_row;
exception when unique_violation then
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_id<>'prestamo'
       or v_row.program_item_id<>p_program_item_id or v_row.requested_amount<>p_amount or v_row.requested_term<>p_term then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.register_company_ficha_image(p_company_id uuid, p_path text, p_sha256 text, p_mime text, p_size bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
 if not public.can_upload_company_ficha(p_path) or split_part(p_path,'/',3)<>p_company_id::text then raise exception 'COMPANY_ASSET_DENIED';end if;
 if p_mime not in('image/jpeg','image/png','image/webp','image/gif') or p_size not between 1 and 10485760 or p_sha256!~'^[a-fA-F0-9]{64}$' then raise exception 'INVALID_IMAGE';end if;
 if not exists(select 1 from storage.objects where bucket_id='company-assets' and name=p_path and (metadata->>'size')::bigint=p_size and metadata->>'mimetype'=p_mime) then raise exception 'UPLOADED_IMAGE_REQUIRED';end if;
 insert into public.app_assets(asset_key,asset_type,title,alt_text,storage_bucket,storage_path,mime_type,file_size,content_sha256,status,owner_company_id)
 values('company.ficha.'||extensions.gen_random_uuid(),'COMPANY','Imagen empresarial','Imagen empresarial','company-assets',p_path,p_mime,p_size,upper(p_sha256),'READY',p_company_id) returning id into v_id;
 return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.register_admin_affiliate_document(p_affiliate_id uuid, p_document_type_id uuid, p_storage_path text, p_mime_type text, p_file_size bigint, p_sha256 text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_type public.document_types%rowtype;v_asset public.private_assets%rowtype;v_doc public.affiliate_documents%rowtype;v_replaced uuid;v_path text:=btrim(coalesce(p_storage_path,''));v_reason text:=btrim(coalesce(p_reason,''));v_cleanup_path text;
begin
  if not public.has_admin_permission('documents.write') then raise exception 'ADMIN_DOCUMENT_WRITE_DENIED' using errcode='42501'; end if;
  if auth.uid() is null or not exists(select 1 from public.affiliates where id=p_affiliate_id) then raise exception 'AFFILIATE_NOT_FOUND' using errcode='22023'; end if;
  if length(v_reason)>500 then raise exception 'DOCUMENT_REASON_TOO_LONG' using errcode='22023'; end if;
  select * into v_type from public.document_types where id=p_document_type_id and enabled;
  if v_type.id is null then raise exception 'DOCUMENT_TYPE_UNAVAILABLE' using errcode='22023'; end if;
  if not v_type.file_upload_allowed or not(p_mime_type=any(v_type.accepted_mime_types)) or p_file_size<1 or p_file_size>v_type.max_file_size_bytes or upper(coalesce(p_sha256,''))!~'^[A-F0-9]{64}$' then raise exception 'INVALID_DOCUMENT_FILE' using errcode='22023'; end if;
  if v_path!~('^affiliate-documents/'||p_affiliate_id::text||'/[A-Za-z0-9._-]+$') then raise exception 'INVALID_STORAGE_PATH' using errcode='22023'; end if;
  if not exists(select 1 from storage.objects where bucket_id='private-assets' and name=v_path and owner_id=auth.uid()::text) then raise exception 'UPLOAD_NOT_FOUND' using errcode='22023'; end if;
  select d.id into v_replaced from document_retirement_private.active_documents d where d.affiliate_id=p_affiliate_id and d.document_type_id=p_document_type_id order by d.created_at desc,d.id desc limit 1;
  select * into v_asset from public.private_assets where content_sha256=upper(p_sha256) for update;
  if v_asset.id is null then begin
    insert into public.private_assets(asset_key,asset_type,title,storage_bucket,storage_path,mime_type,file_size,content_sha256)
    values('affiliate_document_'||replace(extensions.gen_random_uuid()::text,'-',''),'AFFILIATE_DOCUMENT',v_type.label,'private-assets',v_path,p_mime_type,p_file_size,upper(p_sha256)) returning * into v_asset;
  exception when unique_violation then select * into v_asset from public.private_assets where content_sha256=upper(p_sha256) for update;end;end if;
  if v_asset.id is null then raise exception 'DOCUMENT_ASSET_REGISTRATION_FAILED'; end if;
  if v_asset.storage_path is distinct from v_path then v_cleanup_path:=v_path; end if;
  update public.affiliate_documents set status='REJECTED',review_observation='Reemplazado por una nueva carga administrativa.',reviewed_by_auth_user_id=auth.uid(),reviewed_at=now()
   where public.affiliate_document_is_active(id) and affiliate_id=p_affiliate_id and document_type_id=p_document_type_id and status in('PENDING_REVIEW','UNDER_REVIEW','REUPLOAD_REQUIRED');
  insert into public.affiliate_documents(affiliate_id,document_type_id,private_asset_id,status,created_by_auth_user_id,replaces_document_id)
   values(p_affiliate_id,p_document_type_id,v_asset.id,'PENDING_REVIEW',auth.uid(),v_replaced) returning * into v_doc;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
   values(auth.uid(),p_affiliate_id,'affiliate_documents',case when v_replaced is null then 'ADMIN_UPLOAD' else 'ADMIN_REPLACEMENT_UPLOAD' end,v_doc.id,jsonb_strip_nulls(jsonb_build_object('document_type_id',p_document_type_id,'mime_type',p_mime_type,'file_size',p_file_size,'reason',v_reason,'replaces_document_id',v_replaced)));
  return jsonb_build_object('document',to_jsonb(v_doc),'cleanup_storage_path',v_cleanup_path);
end $function$

CREATE OR REPLACE FUNCTION public.create_validated_financial_program_request(p_actor_real_auth_user_id uuid, p_affiliate_id uuid, p_impersonation_session_id uuid, p_program_item_id uuid, p_notes text, p_signature_data text, p_terms_version_id uuid, p_document_ids uuid[], p_idempotency_key uuid, p_amount numeric, p_term integer, p_term_semantics text, p_expected_profile_version integer, p_financial_submission_snapshot jsonb)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_item public.program_catalog_items%rowtype;
  v_ctx public.impersonation_sessions%rowtype;
  v_row public.program_requests%rowtype;
  v_deposit public.loan_request_deposit_snapshots%rowtype;
  v_submission jsonb;
  v_phone text;
  v_bank_text text;
  v_missing integer;
begin
  v_bank_text:=nullif(btrim(coalesce(p_financial_submission_snapshot->'deposit_selection'->>'bank_account_id','')),'');
  if v_bank_text is not null then
    return public.create_validated_financial_program_request_bank_required(
      p_actor_real_auth_user_id,p_affiliate_id,p_impersonation_session_id,p_program_item_id,p_notes,
      p_signature_data,p_terms_version_id,p_document_ids,p_idempotency_key,p_amount,p_term,
      p_term_semantics,p_expected_profile_version,p_financial_submission_snapshot
    );
  end if;

  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_actor_real_auth_user_id is null or not exists(select 1 from auth.users where id=p_actor_real_auth_user_id) then
    raise exception 'AUTH_ACTOR_REQUIRED' using errcode='42501';
  end if;
  select * into v_affiliate from public.affiliates where id=p_affiliate_id for update;
  if v_affiliate.id is null or v_affiliate.financial_profile_version<>p_expected_profile_version then
    raise exception 'CONDITIONS_CHANGED' using errcode='PT409';
  end if;
  if p_impersonation_session_id is null then
    if v_affiliate.auth_user_id is distinct from p_actor_real_auth_user_id then raise exception 'AFFILIATE_CONTEXT_DENIED' using errcode='42501'; end if;
  else
    select * into v_ctx from public.impersonation_sessions where id=p_impersonation_session_id for share;
    if v_ctx.id is null or v_ctx.actor_real_auth_user_id<>p_actor_real_auth_user_id
       or v_ctx.usuario_contexto_affiliate_id<>p_affiliate_id or v_ctx.ended_at is not null or v_ctx.expires_at<=now()
       or not exists(select 1 from public.admin_assignments a join public.admin_roles r on r.id=a.role_id and r.enabled where a.auth_user_id=p_actor_real_auth_user_id and a.enabled) then
      raise exception 'IMPERSONATION_CONTEXT_INVALID' using errcode='42501';
    end if;
  end if;
  select * into v_item from public.program_catalog_items
   where id=p_program_item_id and program_key='prestamo' and enabled and request_mode='supabase' and legacy_boundary;
  if v_item.id is null then raise exception 'PROGRAM_NOT_REQUESTABLE' using errcode='22023'; end if;
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_signature_data,'')),'') is null then raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023'; end if;
  if p_amount is null or p_amount<=0 or p_term is null or p_term<=0 or length(btrim(coalesce(p_term_semantics,''))) not between 3 and 80 then
    raise exception 'FINANCIAL_REQUEST_TERMS_INVALID' using errcode='22023';
  end if;
  if not exists(select 1 from public.program_terms_versions where id=p_terms_version_id and program_id='prestamo' and membership_offering_id is null and published) then
    raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023';
  end if;
  if p_financial_submission_snapshot is null
     or jsonb_typeof(p_financial_submission_snapshot)<>'object'
     or not(p_financial_submission_snapshot ?& array[
       'affiliate_id','actor_real_auth_user_id','profile_version','profile_fingerprint',
       'criteria_source_fingerprint','term_policy_fingerprint','calculation_contract_version',
       'criterion_identity','financialResult','confirmed_at','deposit_selection'
     ])
     or jsonb_typeof(p_financial_submission_snapshot->'financialResult')<>'object'
     or jsonb_typeof(p_financial_submission_snapshot->'deposit_selection')<>'object'
     or nullif(btrim(coalesce(p_financial_submission_snapshot->'deposit_selection'->>'bank_account_id','')),'') is not null
     or p_financial_submission_snapshot->>'affiliate_id'<>p_affiliate_id::text
     or p_financial_submission_snapshot->>'actor_real_auth_user_id'<>p_actor_real_auth_user_id::text
     or coalesce(p_financial_submission_snapshot->>'impersonation_session_id','')<>coalesce(p_impersonation_session_id::text,'')
     or (p_financial_submission_snapshot->>'profile_version')::integer<>p_expected_profile_version
     or (p_financial_submission_snapshot->'financialResult'->>'amount')::numeric<>p_amount
     or (p_financial_submission_snapshot->'financialResult'->>'paymentCount')::integer<>p_term then
    raise exception 'FINANCIAL_SUBMISSION_CONTRACT_MISMATCH' using errcode='22023';
  end if;
  v_phone:=p_financial_submission_snapshot->'deposit_selection'->>'notification_phone';
  if coalesce(v_phone,'') !~ '^[0-9]{10}$' then raise exception 'INVALID_NOTIFICATION_PHONE' using errcode='22023'; end if;

  v_submission:=(p_financial_submission_snapshot-'deposit_selection') || jsonb_build_object('deposit',jsonb_build_object(
    'bank_account_id',null,'bank_name',null,'masked_card',null,'masked_clabe',null,
    'masked_phone','••• ••• '||right(v_phone,4)
  ));

  select count(*) into v_missing from public.resolve_affiliate_document_requirements('PROGRAM','prestamo',p_affiliate_id) r
   where r.required and not exists(
     select 1 from public.affiliate_documents d where d.id=any(coalesce(p_document_ids,array[]::uuid[]))
       and d.affiliate_id=p_affiliate_id and d.document_type_id=r.document_type_id
       and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED'));
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;

  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_id<>'prestamo'
       or v_row.program_item_id<>p_program_item_id or v_row.requested_amount<>p_amount or v_row.requested_term<>p_term then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    select * into v_deposit from public.loan_request_deposit_snapshots where request_id=v_row.id;
    if v_deposit.request_id is null or v_deposit.source_bank_account_id is not null or v_deposit.notification_phone<>v_phone then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;

  insert into public.program_requests(
    actor_real_auth_user_id,affiliate_id,usuario_contexto_affiliate_id,impersonation_session_id,impersonation_reason,
    numero_control,program_id,program_item_id,request_type,status,quantity,notes,signature_data,terms_accepted,
    terms_version_id,source_context,financial_processing_status,idempotency_key,requested_amount,requested_term,
    requested_term_semantics,financial_submission_snapshot
  ) values(
    p_actor_real_auth_user_id,p_affiliate_id,case when v_ctx.id is null then null else p_affiliate_id end,v_ctx.id,v_ctx.reason,
    v_affiliate.numero_control,'prestamo',v_item.id,'quote','requires_financial_processing',1,
    left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,p_terms_version_id,
    jsonb_build_object('source','sutiapp','financial_confirmation','SUPABASE_REVALIDATED','assisted',v_ctx.id is not null),
    'pending',p_idempotency_key,p_amount,p_term,btrim(p_term_semantics),v_submission
  ) returning * into v_row;

  insert into public.loan_request_deposit_snapshots(request_id,affiliate_id,notification_phone)
  values(v_row.id,p_affiliate_id,v_phone);
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(p_actor_real_auth_user_id,p_affiliate_id,'program_requests','LOAN_DEPOSIT_CONFIRMED',v_row.id,
    jsonb_build_object('has_bank_account',false,'phone_last4',right(v_phone,4)));

  insert into public.request_documents(request_id,document_type_id,affiliate_document_id,private_asset_id,asset_sha256,status_at_submission)
  select v_row.id,d.document_type_id,d.id,coalesce(d.private_asset_id,af.private_asset_id),pa.content_sha256,d.status
  from public.affiliate_documents d left join public.affiliate_files af on af.id=d.affiliate_file_id
  join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id)
  where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
    and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
  on conflict(request_id,document_type_id) do nothing;
  return v_row;
exception when unique_violation then
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_id<>'prestamo'
       or v_row.program_item_id<>p_program_item_id or v_row.requested_amount<>p_amount or v_row.requested_term<>p_term then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    select * into v_deposit from public.loan_request_deposit_snapshots where request_id=v_row.id;
    if v_deposit.request_id is null or v_deposit.source_bank_account_id is not null or v_deposit.notification_phone<>v_phone then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.create_validated_financial_program_request_bank_required(p_actor_real_auth_user_id uuid, p_affiliate_id uuid, p_impersonation_session_id uuid, p_program_item_id uuid, p_notes text, p_signature_data text, p_terms_version_id uuid, p_document_ids uuid[], p_idempotency_key uuid, p_amount numeric, p_term integer, p_term_semantics text, p_expected_profile_version integer, p_financial_submission_snapshot jsonb)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_item public.program_catalog_items%rowtype;
  v_ctx public.impersonation_sessions%rowtype;
  v_row public.program_requests%rowtype;
  v_bank public.affiliate_bank_accounts%rowtype;
  v_deposit public.loan_request_deposit_snapshots%rowtype;
  v_submission jsonb;
  v_phone text;
  v_bank_id uuid;
  v_missing integer;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_actor_real_auth_user_id is null or not exists(select 1 from auth.users where id=p_actor_real_auth_user_id) then
    raise exception 'AUTH_ACTOR_REQUIRED' using errcode='42501';
  end if;
  select * into v_affiliate from public.affiliates where id=p_affiliate_id for update;
  if v_affiliate.id is null or v_affiliate.financial_profile_version<>p_expected_profile_version then
    raise exception 'CONDITIONS_CHANGED' using errcode='PT409';
  end if;
  if p_impersonation_session_id is null then
    if v_affiliate.auth_user_id is distinct from p_actor_real_auth_user_id then raise exception 'AFFILIATE_CONTEXT_DENIED' using errcode='42501'; end if;
  else
    select * into v_ctx from public.impersonation_sessions where id=p_impersonation_session_id for share;
    if v_ctx.id is null or v_ctx.actor_real_auth_user_id<>p_actor_real_auth_user_id
       or v_ctx.usuario_contexto_affiliate_id<>p_affiliate_id or v_ctx.ended_at is not null or v_ctx.expires_at<=now()
       or not exists(select 1 from public.admin_assignments a join public.admin_roles r on r.id=a.role_id and r.enabled where a.auth_user_id=p_actor_real_auth_user_id and a.enabled) then
      raise exception 'IMPERSONATION_CONTEXT_INVALID' using errcode='42501';
    end if;
  end if;
  select * into v_item from public.program_catalog_items
   where id=p_program_item_id and program_key='prestamo' and enabled and request_mode='supabase' and legacy_boundary;
  if v_item.id is null then raise exception 'PROGRAM_NOT_REQUESTABLE' using errcode='22023'; end if;
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_signature_data,'')),'') is null then raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023'; end if;
  if p_amount is null or p_amount<=0 or p_term is null or p_term<=0 or length(btrim(coalesce(p_term_semantics,''))) not between 3 and 80 then
    raise exception 'FINANCIAL_REQUEST_TERMS_INVALID' using errcode='22023';
  end if;
  if not exists(select 1 from public.program_terms_versions where id=p_terms_version_id and program_id='prestamo' and membership_offering_id is null and published) then
    raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023';
  end if;
  if p_financial_submission_snapshot is null
     or jsonb_typeof(p_financial_submission_snapshot)<>'object'
     or not(p_financial_submission_snapshot ?& array[
       'affiliate_id','actor_real_auth_user_id','profile_version','profile_fingerprint',
       'criteria_source_fingerprint','term_policy_fingerprint','calculation_contract_version',
       'criterion_identity','financialResult','confirmed_at','deposit_selection'
     ])
     or jsonb_typeof(p_financial_submission_snapshot->'financialResult')<>'object'
     or jsonb_typeof(p_financial_submission_snapshot->'deposit_selection')<>'object'
     or p_financial_submission_snapshot->>'affiliate_id'<>p_affiliate_id::text
     or p_financial_submission_snapshot->>'actor_real_auth_user_id'<>p_actor_real_auth_user_id::text
     or coalesce(p_financial_submission_snapshot->>'impersonation_session_id','')<>coalesce(p_impersonation_session_id::text,'')
     or (p_financial_submission_snapshot->>'profile_version')::integer<>p_expected_profile_version
     or (p_financial_submission_snapshot->'financialResult'->>'amount')::numeric<>p_amount
     or (p_financial_submission_snapshot->'financialResult'->>'paymentCount')::integer<>p_term then
    raise exception 'FINANCIAL_SUBMISSION_CONTRACT_MISMATCH' using errcode='22023';
  end if;
  begin
    v_bank_id:=(p_financial_submission_snapshot->'deposit_selection'->>'bank_account_id')::uuid;
  exception when others then
    raise exception 'INVALID_DEPOSIT_ACCOUNT' using errcode='22023';
  end;
  v_phone:=p_financial_submission_snapshot->'deposit_selection'->>'notification_phone';
  if coalesce(v_phone,'') !~ '^[0-9]{10}$' then raise exception 'INVALID_NOTIFICATION_PHONE' using errcode='22023'; end if;
  select * into v_bank from public.affiliate_bank_accounts
   where id=v_bank_id and affiliate_id=p_affiliate_id and data_status='COMPLETE'
     and (card_number ~ '^[0-9]{16}$' or public.is_valid_clabe(clabe))
     and (card_number is null or card_number ~ '^[0-9]{16}$')
     and (clabe is null or public.is_valid_clabe(clabe))
   for share;
  if v_bank.id is null then raise exception 'DEPOSIT_ACCOUNT_UNAVAILABLE' using errcode='42501'; end if;

  v_submission:=(p_financial_submission_snapshot-'deposit_selection') || jsonb_build_object('deposit',jsonb_build_object(
    'bank_account_id',v_bank.id,'bank_name',v_bank.bank_name,
    'masked_card','•••• '||right(v_bank.card_number,4),
    'masked_clabe','•••• •••• •••• ••'||right(v_bank.clabe,4),
    'masked_phone','••• ••• '||right(v_phone,4)
  ));

  select count(*) into v_missing from public.resolve_affiliate_document_requirements('PROGRAM','prestamo',p_affiliate_id) r
   where r.required and not exists(
     select 1 from public.affiliate_documents d where d.id=any(coalesce(p_document_ids,array[]::uuid[]))
       and d.affiliate_id=p_affiliate_id and d.document_type_id=r.document_type_id
       and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED'));
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;

  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_id<>'prestamo'
       or v_row.program_item_id<>p_program_item_id or v_row.requested_amount<>p_amount or v_row.requested_term<>p_term then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    select * into v_deposit from public.loan_request_deposit_snapshots where request_id=v_row.id;
    if v_deposit.request_id is null or v_deposit.source_bank_account_id<>v_bank.id or v_deposit.notification_phone<>v_phone then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;

  insert into public.program_requests(
    actor_real_auth_user_id,affiliate_id,usuario_contexto_affiliate_id,impersonation_session_id,impersonation_reason,
    numero_control,program_id,program_item_id,request_type,status,quantity,notes,signature_data,terms_accepted,
    terms_version_id,source_context,financial_processing_status,idempotency_key,requested_amount,requested_term,
    requested_term_semantics,financial_submission_snapshot
  ) values(
    p_actor_real_auth_user_id,p_affiliate_id,case when v_ctx.id is null then null else p_affiliate_id end,v_ctx.id,v_ctx.reason,
    v_affiliate.numero_control,'prestamo',v_item.id,'quote','requires_financial_processing',1,
    left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,p_terms_version_id,
    jsonb_build_object('source','sutiapp','financial_confirmation','SUPABASE_REVALIDATED','assisted',v_ctx.id is not null),
    'pending',p_idempotency_key,p_amount,p_term,btrim(p_term_semantics),v_submission
  ) returning * into v_row;

  insert into public.loan_request_deposit_snapshots(
    request_id,affiliate_id,source_bank_account_id,bank_name,account_holder,card_number,clabe,notification_phone
  ) values(
    v_row.id,p_affiliate_id,v_bank.id,v_bank.bank_name,v_bank.account_holder,v_bank.card_number,v_bank.clabe,v_phone
  );
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(p_actor_real_auth_user_id,p_affiliate_id,'program_requests','LOAN_DEPOSIT_SELECTED',v_row.id,
    jsonb_build_object('bank_account_id',v_bank.id,'card_last4',right(v_bank.card_number,4),'clabe_last4',right(v_bank.clabe,4),'phone_last4',right(v_phone,4)));

  insert into public.request_documents(request_id,document_type_id,affiliate_document_id,private_asset_id,asset_sha256,status_at_submission)
  select v_row.id,d.document_type_id,d.id,coalesce(d.private_asset_id,af.private_asset_id),pa.content_sha256,d.status
  from public.affiliate_documents d left join public.affiliate_files af on af.id=d.affiliate_file_id
  join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id)
  where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
    and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
  on conflict(request_id,document_type_id) do nothing;
  return v_row;
exception when unique_violation then
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_id<>'prestamo'
       or v_row.program_item_id<>p_program_item_id or v_row.requested_amount<>p_amount or v_row.requested_term<>p_term then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    select * into v_deposit from public.loan_request_deposit_snapshots where request_id=v_row.id;
    if v_deposit.request_id is null or v_deposit.source_bank_account_id<>v_bank.id or v_deposit.notification_phone<>v_phone then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.create_validated_program_product_payment_request(p_actor_real_auth_user_id uuid, p_affiliate_id uuid, p_impersonation_session_id uuid, p_program_item_id uuid, p_notes text, p_signature_data text, p_terms_version_id uuid, p_document_ids uuid[], p_idempotency_key uuid, p_down_payment numeric, p_term integer, p_expected_profile_version integer, p_schedule_anchor_date date)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_item public.program_catalog_items%rowtype;
  v_ctx public.impersonation_sessions%rowtype;
  v_quote public.program_requests%rowtype;
  v_row public.program_requests%rowtype;
  v_policy public.loan_term_policy%rowtype;
  v_rules jsonb;
  v_rule jsonb; v_financing jsonb;
  v_rule_count integer;
  v_price numeric(14,2);
  v_amount numeric(14,2);
  v_source text;
  v_result jsonb;
  v_schedule jsonb;
  v_process text;
  v_period text;
  v_union_label text;
  v_category_label text;
  v_missing integer;
  v_snapshot jsonb;
  v_business_date date:=(now() at time zone 'America/Hermosillo')::date;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_actor_real_auth_user_id is null or not exists(select 1 from auth.users where id=p_actor_real_auth_user_id) then
    raise exception 'AUTH_ACTOR_REQUIRED' using errcode='42501';
  end if;
  select * into v_affiliate from public.affiliates where id=p_affiliate_id for update;
  if v_affiliate.id is null or v_affiliate.financial_profile_version<>p_expected_profile_version then
    raise exception 'CONDITIONS_CHANGED' using errcode='PT409';
  end if;
  if p_impersonation_session_id is null then
    if v_affiliate.auth_user_id is distinct from p_actor_real_auth_user_id then raise exception 'AFFILIATE_CONTEXT_DENIED' using errcode='42501'; end if;
  else
    select * into v_ctx from public.impersonation_sessions where id=p_impersonation_session_id for share;
    if v_ctx.id is null or v_ctx.actor_real_auth_user_id<>p_actor_real_auth_user_id
       or v_ctx.usuario_contexto_affiliate_id<>p_affiliate_id or v_ctx.ended_at is not null or v_ctx.expires_at<=now()
       or not exists(select 1 from public.admin_assignments a join public.admin_roles r on r.id=a.role_id and r.enabled
         where a.auth_user_id=p_actor_real_auth_user_id and a.enabled) then
      raise exception 'IMPERSONATION_CONTEXT_INVALID' using errcode='42501';
    end if;
  end if;
  select * into v_item from public.program_catalog_items where id=p_program_item_id and enabled and request_mode='supabase' for share;
  if v_item.id is null or v_item.program_key='prestamo' then raise exception 'PROGRAM_PRODUCT_NOT_FINANCEABLE' using errcode='22023'; end if;
  if v_item.requires_quote then
    select * into v_quote from public.program_requests
    where affiliate_id=p_affiliate_id and program_item_id=v_item.id and request_type='quote' and status='approved'
      and quoted_amount>0 and (valid_until is null or valid_until>=v_business_date)
    order by responded_at desc nulls last,created_at desc,id desc limit 1 for share;
    if v_quote.id is null then raise exception 'AUTHORIZED_PRODUCT_PRICE_UNAVAILABLE' using errcode='P0001'; end if;
    v_price:=v_quote.quoted_amount;v_source:='APPROVED_QUOTE';
  else
    if v_item.price_cash is null or v_item.price_cash<=0 then raise exception 'AUTHORIZED_PRODUCT_PRICE_UNAVAILABLE' using errcode='P0001'; end if;
    v_price:=v_item.price_cash;v_source:='PRICE_CASH';
  end if;
  if p_down_payment is null or p_down_payment<0 or p_down_payment>=v_price then raise exception 'DOWN_PAYMENT_OUT_OF_RANGE' using errcode='22023'; end if;
  v_amount:=round(v_price-p_down_payment,2);
  select * into v_policy from public.loan_term_policy where id='primary' and enabled;
  if v_policy.id is null then raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001'; end if;
  select u.label,c.label into v_union_label,v_category_label
  from public.affiliates a
  left join public.segmentation_catalog_entries u on u.catalog_type='union' and u.code=a.financial_union_code and u.enabled
  left join public.segmentation_catalog_entries c on c.catalog_type='employment_category' and c.code=a.financial_employee_category_code and c.enabled
  where a.id=v_affiliate.id;
  if v_union_label is null or v_category_label is null then raise exception 'AFFILIATE_FINANCIAL_PROFILE_INCOMPLETE' using errcode='P0001'; end if;
  v_rules:=public.get_financial_runtime_rules();
  select count(*) into v_rule_count
  from jsonb_array_elements(v_rules) candidate(value)
  where value->>'program_id'='caja'
    and public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(v_category_label)
    and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(v_union_label)
    and case upper(coalesce(value->>'visibility_mode','AUTO'))
      when 'MOSTRAR' then true when 'OCULTAR' then false
      else value->>'available_on' is null or (value->>'available_on')::date between v_business_date
        and (date_trunc('month',v_business_date)+interval '5 months - 1 day')::date end;
  if v_rule_count<>1 then raise exception 'CAJA_CHICA_RULE_NOT_ELIGIBLE' using errcode='P0001'; end if;
  select value into v_rule
  from jsonb_array_elements(v_rules) candidate(value)
  where value->>'program_id'='caja'
    and public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(v_category_label)
    and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(v_union_label)
    and case upper(coalesce(value->>'visibility_mode','AUTO'))
      when 'MOSTRAR' then true when 'OCULTAR' then false
      else value->>'available_on' is null or (value->>'available_on')::date between v_business_date
        and (date_trunc('month',v_business_date)+interval '5 months - 1 day')::date end
  limit 1;
  v_rule:=v_rule||jsonb_build_object('status','AVAILABLE');
  v_financing:=public.resolve_program_product_financing(v_item.id,v_affiliate.id,v_rule,v_price);
  v_rule:=v_financing->'rule';
  if p_down_payment<>(round(p_down_payment,2)) or p_down_payment<(v_financing->>'minimum_down_payment')::numeric then raise exception 'DOWN_PAYMENT_OUT_OF_RANGE' using errcode='22023'; end if;
  v_result:=public.resolve_suti_loan_quote_contract(
    jsonb_build_array(v_rule),v_union_label,v_category_label,
    v_rule->>'id',v_amount,p_term,jsonb_build_object(
      'source','SUPABASE_LOAN_TERM_POLICY','standardTerms',v_policy.standard_terms,
      'customMinTerm',v_policy.custom_min_term,'customStep',v_policy.custom_step,
      'decisionReference',v_policy.decision_reference
    )
  );
  v_process:=case v_affiliate.financial_employee_category_code
    when 'SUPLENTES_VARIABLES' then '3' when 'JUBILADOS_PENSIONADOS' then 'JUB'
    when 'SUPLENTES_FIJOS' then '1' when 'EVENTUALES' then '1' when 'BASE' then '1'
    else null end;
  if v_process is null then raise exception 'PAYROLL_PROCESS_UNRESOLVED' using errcode='P0001'; end if;
  v_period:=case when v_process='JUB' then 'mensual' else 'quincenal' end;
  v_result:=(v_result||jsonb_build_object('paymentPeriod',v_period,'ratePeriod',v_period,'source','SUPABASE_FINANCIAL_CRITERIA'));
  if p_schedule_anchor_date is distinct from v_business_date then raise exception 'SCHEDULE_ANCHOR_CHANGED' using errcode='PT409'; end if;
  v_schedule:=public.generate_program_product_payment_schedule(
    p_schedule_anchor_date,v_process,(v_result->>'paymentCount')::integer,
    (v_result->>'total')::numeric,(v_result->>'paymentPerPeriod')::numeric
  );
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_signature_data,'')),'') is null then raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023'; end if;
  if not exists(select 1 from public.program_terms_versions where id=p_terms_version_id and program_id='prestamo'
    and membership_offering_id is null and published) then raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023'; end if;
  select count(*) into v_missing
  from public.resolve_affiliate_document_requirements('PROGRAM','prestamo',p_affiliate_id) requirement
  where requirement.required and not exists(
    select 1 from public.affiliate_documents d
    left join public.affiliate_files af on af.id=d.affiliate_file_id
    join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id) and pa.status='READY'
    join storage.objects so on so.bucket_id=pa.storage_bucket and so.name=pa.storage_path
    where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
      and d.document_type_id=requirement.document_type_id and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
      and not exists(select 1 from public.affiliate_documents newer where newer.affiliate_id=d.affiliate_id
        and newer.document_type_id=d.document_type_id and (newer.created_at,newer.id)>(d.created_at,d.id))
  );
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;
  v_snapshot:=jsonb_build_object(
    'contract_version','PROGRAM_PRODUCT_PAYMENT_V1','calculation_contract_version','SUTI_LOAN_QUOTE_V1',
    'calendar_contract_version','PROGRAM_PRODUCT_PAYROLL_CALENDAR_V1','affiliate_id',p_affiliate_id,
    'actor_real_auth_user_id',p_actor_real_auth_user_id,'impersonation_session_id',p_impersonation_session_id,
    'profile_version',v_affiliate.financial_profile_version,'product',jsonb_build_object(
      'program_item_id',v_item.id,'program_key',v_item.program_key,'name',v_item.name
    ),'authorized_price',v_price,'price_source',v_source,'quote_request_id',v_quote.id,
    'down_payment',round(p_down_payment,2),'financed_amount',v_amount,'fund_program_id','caja',
    'fund_rule_id',v_rule->>'rule_id','criterion_identity',v_rule->>'criterion_identity',
    'financial_authority','SUPABASE','financial_rules_source_hash',v_rule->>'source_snapshot_hash',
    'financing_conditions',v_financing->'conditions','financialResult',v_result,'payment_schedule',v_schedule,'terms_version_id',p_terms_version_id,
    'confirmed_at',now()
  );
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_item_id<>p_program_item_id
       or v_row.requested_amount<>v_amount or v_row.requested_term<>p_term
       or (v_row.financial_submission_snapshot->>'down_payment')::numeric<>round(p_down_payment,2)
       or v_row.financial_submission_snapshot->>'price_source'<>v_source
       or coalesce(v_row.financial_submission_snapshot->>'quote_request_id','')<>coalesce(v_quote.id::text,'') then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;
  insert into public.program_requests(
    actor_real_auth_user_id,affiliate_id,usuario_contexto_affiliate_id,impersonation_session_id,impersonation_reason,
    numero_control,program_id,program_item_id,request_type,status,quantity,notes,signature_data,terms_accepted,
    terms_version_id,source_context,financial_processing_status,idempotency_key,requested_amount,requested_term,
    requested_term_semantics,financial_submission_snapshot
  ) values(
    p_actor_real_auth_user_id,p_affiliate_id,case when v_ctx.id is null then null else p_affiliate_id end,v_ctx.id,v_ctx.reason,
    v_affiliate.numero_control,v_item.program_key,v_item.id,'benefit','requires_financial_processing',1,
    left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,p_terms_version_id,
    jsonb_build_object('source','sutiapp','flow','PROGRAM_PRODUCT_PAYMENT_V1','price_source',v_source,
      'quote_request_id',v_quote.id,'fund_program_id','caja','assisted',v_ctx.id is not null),
    'pending',p_idempotency_key,v_amount,p_term,v_period,v_snapshot
  ) returning * into v_row;
  insert into public.request_documents(request_id,document_type_id,affiliate_document_id,private_asset_id,asset_sha256,status_at_submission)
  select v_row.id,d.document_type_id,d.id,coalesce(d.private_asset_id,af.private_asset_id),pa.content_sha256,d.status
  from public.affiliate_documents d left join public.affiliate_files af on af.id=d.affiliate_file_id
  join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id)
  join storage.objects so on so.bucket_id=pa.storage_bucket and so.name=pa.storage_path
  where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
    and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
  on conflict(request_id,document_type_id) do nothing;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(p_actor_real_auth_user_id,p_affiliate_id,'program_requests','PROGRAM_PRODUCT_PAYMENT_CONFIRMED',v_row.id,
    jsonb_build_object('program_item_id',v_item.id,'price_source',v_source,'quote_request_id',v_quote.id,
      'payment_count',p_term,'payment_period',v_period,'assisted',v_ctx.id is not null));
  return v_row;
exception when unique_violation then
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null and v_row.program_item_id=p_program_item_id and v_row.requested_amount=v_amount
     and v_row.requested_term=p_term and (v_row.financial_submission_snapshot->>'down_payment')::numeric=round(p_down_payment,2) then
    return v_row;
  end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.register_branding_assets(p_assets jsonb)
 RETURNS TABLE(asset_key text, asset_id uuid, previous_storage_bucket text, previous_storage_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item jsonb;
  v_asset_key text;
  v_storage_path text;
  v_mime_type text;
  v_file_size bigint;
  v_content_sha256 text;
  v_extension text;
  v_expected_path text;
  v_asset_id uuid;
  v_previous_bucket text;
  v_previous_path text;
  v_count integer;
  v_keys text[] := array[]::text[];
begin
  if not (public.has_admin_permission('assets.write') and public.admin_module_boundary(array['branding'],'update')) then
    raise exception 'ADMIN_DENIED' using errcode = '42501';
  end if;

  if jsonb_typeof(p_assets) <> 'array' then
    raise exception 'INVALID_ASSET_BATCH' using errcode = '22023';
  end if;
  v_count := jsonb_array_length(p_assets);
  if v_count < 1 or v_count > 4 then
    raise exception 'INVALID_ASSET_BATCH' using errcode = '22023';
  end if;

  for v_item in select value from jsonb_array_elements(p_assets)
  loop
    v_asset_key := nullif(trim(v_item->>'asset_key'), '');
    v_storage_path := nullif(trim(v_item->>'storage_path'), '');
    v_mime_type := nullif(trim(v_item->>'mime_type'), '');
    v_content_sha256 := upper(nullif(trim(v_item->>'content_sha256'), ''));
    begin
      v_file_size := (v_item->>'file_size')::bigint;
    exception when others then
      raise exception 'INVALID_ASSET_FILE_SIZE' using errcode = '22023';
    end;

    if v_asset_key is null or not (v_asset_key = any(array[
      'brand.pwa.512',
      'brand.institutional-seal',
      'brand.favicon-pwa-192',
      'brand.pwa.apple-touch',
      'brand.pwa.maskable-512',
      'pwa.install-screen-1',
      'pwa.install-screen-2',
      'pwa.install-screen-3',
      'home.header.collapsed'
    ]::text[])) then
      raise exception 'UNKNOWN_BRANDING_ASSET' using errcode = '22023';
    end if;
    if v_asset_key = any(v_keys) then
      raise exception 'DUPLICATE_BRANDING_ASSET' using errcode = '22023';
    end if;
    v_keys := array_append(v_keys, v_asset_key);

    v_extension := case v_mime_type
      when 'image/png' then 'png'
      when 'image/jpeg' then 'jpg'
      when 'image/gif' then 'gif'
      when 'image/webp' then 'webp'
      when 'image/svg+xml' then 'svg'
      when 'image/x-icon' then 'ico'
      else null
    end;
    if v_extension is null or v_file_size < 1 or v_file_size > 10485760
       or v_content_sha256 !~ '^[A-F0-9]{64}$' then
      raise exception 'INVALID_BRANDING_ASSET' using errcode = '22023';
    end if;

    v_expected_path := 'branding/admin/' ||
      regexp_replace(v_asset_key, '[^a-zA-Z0-9._-]', '-', 'g') || '/' ||
      lower(v_content_sha256) || '.' || v_extension;
    if v_storage_path is distinct from v_expected_path then
      raise exception 'INVALID_BRANDING_STORAGE_PATH' using errcode = '22023';
    end if;
    if not exists(
      select 1 from storage.objects o
      where o.bucket_id = 'app-assets' and o.name = v_storage_path
    ) then
      raise exception 'BRANDING_UPLOAD_NOT_FOUND' using errcode = '22023';
    end if;

    select a.id, a.storage_bucket, a.storage_path
      into v_asset_id, v_previous_bucket, v_previous_path
    from public.app_assets a
    where a.asset_key = v_asset_key
    for update;

    if v_asset_id is null then
      insert into public.app_assets(
        asset_key, asset_type, title, alt_text, storage_bucket, storage_path,
        mime_type, file_size, content_sha256, status
      ) values (
        v_asset_key, 'BRANDING', v_asset_key, replace(v_asset_key, '.', ' '),
        'app-assets', v_storage_path, v_mime_type, v_file_size,
        v_content_sha256, 'READY'
      ) returning id into v_asset_id;
    else
      update public.app_assets set
        asset_type = 'BRANDING',
        title = v_asset_key,
        alt_text = replace(v_asset_key, '.', ' '),
        storage_bucket = 'app-assets',
        storage_path = v_storage_path,
        mime_type = v_mime_type,
        file_size = v_file_size,
        content_sha256 = v_content_sha256,
        status = 'READY'
      where id = v_asset_id;
    end if;

    insert into public.asset_sources(
      asset_id, source_sheet, source_column, source_snapshot_hash
    ) values (
      v_asset_id, 'ADMIN_H009', v_asset_key, v_content_sha256
    ) on conflict do nothing;

    case v_asset_key
      when 'brand.pwa.512' then
        update public.app_settings
          set app_icon_asset_id = v_asset_id, pwa_icon_512_asset_id = v_asset_id
        where id = 'primary';
      when 'brand.institutional-seal' then
        update public.app_settings set institutional_seal_asset_id = v_asset_id where id = 'primary';
      when 'brand.favicon-pwa-192' then
        update public.app_settings
          set favicon_asset_id = v_asset_id, pwa_icon_192_asset_id = v_asset_id
        where id = 'primary';
      when 'brand.pwa.apple-touch' then
        update public.app_settings set apple_touch_asset_id = v_asset_id where id = 'primary';
      when 'brand.pwa.maskable-512' then
        update public.app_settings set pwa_maskable_512_asset_id = v_asset_id where id = 'primary';
      when 'pwa.install-screen-1' then
        update public.app_settings set install_screen_1_asset_id = v_asset_id where id = 'primary';
      when 'pwa.install-screen-2' then
        update public.app_settings set install_screen_2_asset_id = v_asset_id where id = 'primary';
      when 'pwa.install-screen-3' then
        update public.app_settings set install_screen_3_asset_id = v_asset_id where id = 'primary';
      when 'home.header.collapsed' then null;
    end case;

    asset_key := v_asset_key;
    asset_id := v_asset_id;
    previous_storage_bucket := v_previous_bucket;
    previous_storage_path := v_previous_path;
    return next;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_self_profile_photo(p_storage_path text, p_mime_type text, p_file_size bigint, p_sha256 text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_asset public.private_assets%rowtype;
  v_previous uuid; v_result uuid; v_meta jsonb;
begin
  select * into v_affiliate from public.affiliates where id=public.get_effective_affiliate_id() for update;
  if auth.uid() is null or v_affiliate.id is null or v_affiliate.auth_user_id is distinct from auth.uid()
    or exists(select 1 from public.get_impersonation_context()) then
    raise exception 'PROFILE_PHOTO_SELF_ONLY' using errcode='42501';
  end if;
  if p_storage_path is null or p_storage_path!~('^affiliate-documents/'||v_affiliate.id::text||'/[a-f0-9-]+\.(jpg|png|webp)$')
    or p_mime_type is null or p_mime_type not in('image/jpeg','image/png','image/webp')
    or p_file_size is null or p_file_size<1 or p_file_size>5242880
    or p_sha256 is null or upper(p_sha256)!~'^[A-F0-9]{64}$' then
    raise exception 'INVALID_PROFILE_PHOTO' using errcode='22023';
  end if;
  select metadata into v_meta from storage.objects where bucket_id='private-assets' and name=p_storage_path and owner_id=auth.uid()::text;
  if v_meta is null or (v_meta->>'size')::bigint is distinct from p_file_size or v_meta->>'mimetype' is distinct from p_mime_type then
    raise exception 'PROFILE_PHOTO_UPLOAD_NOT_FOUND' using errcode='42501';
  end if;
  select id into v_result from public.affiliate_files where affiliate_id=v_affiliate.id and storage_path=p_storage_path and is_current_profile_photo;
  if v_result is not null then return v_result; end if;
  select * into v_asset from public.private_assets where content_sha256=upper(p_sha256);
  if v_asset.id is not null then
    -- Never attach another user's private asset by guessing its hash.
    if not exists(select 1 from public.affiliate_files where affiliate_id=v_affiliate.id and private_asset_id=v_asset.id)
      and not exists(select 1 from public.affiliate_documents where affiliate_id=v_affiliate.id and private_asset_id=v_asset.id) then
      raise exception 'PROFILE_PHOTO_CONTENT_UNAVAILABLE' using errcode='42501';
    end if;
    if v_asset.status<>'READY' or v_asset.mime_type<>p_mime_type or v_asset.file_size<>p_file_size then
      raise exception 'INVALID_PROFILE_PHOTO' using errcode='22023';
    end if;
  else
    insert into public.private_assets(asset_key,asset_type,title,storage_bucket,storage_path,mime_type,file_size,content_sha256)
    values('profile_photo_'||extensions.gen_random_uuid()::text,'AFFILIATE_DOCUMENT','Foto de perfil','private-assets',p_storage_path,p_mime_type,p_file_size,upper(p_sha256)) returning * into v_asset;
  end if;
  select id into v_previous from public.affiliate_files where affiliate_id=v_affiliate.id and is_current_profile_photo;
  update public.affiliate_files set is_current_profile_photo=false where affiliate_id=v_affiliate.id and is_current_profile_photo;
  insert into public.affiliate_files(affiliate_id,numero_control,private_asset_id,classification,file_key,file_type,source_column,source_column_letter,title,storage_bucket,storage_path,mime_type,sha256,file_size,source_url,source_row_ordinal,source_file_hash,expediente_classification,is_current_profile_photo)
  values(v_affiliate.id,v_affiliate.numero_control,v_asset.id,'PRIVATE','profile_photo','image','Photo','DK','Foto de perfil',v_asset.storage_bucket,v_asset.storage_path,v_asset.mime_type,v_asset.content_sha256,v_asset.file_size,
    'supabase://private-assets/'||p_storage_path,coalesce(v_affiliate.source_row_ordinal,1),upper(encode(extensions.digest('PROFILE_UPLOAD:'||p_storage_path,'sha256'),'hex')),'CURRENT_DOCUMENT',true)
  returning id into v_result;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(auth.uid(),v_affiliate.id,'profile_photo','SELF_REPLACE',v_result,jsonb_build_object('previous_file_id',v_previous,'private_asset_id',v_asset.id));
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.prepare_admin_affiliate_document_delete(p_affiliate_id uuid, p_document_id uuid, p_fingerprint text, p_reason text, p_action_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare report jsonb;v_op document_retirement_private.operations%rowtype;ids uuid[];assets uuid[];begin
 if not document_retirement_private.authorized() then raise exception 'AFFILIATE_DOCUMENT_DELETE_DENIED' using errcode='42501';end if;
 if p_action_id is null or length(btrim(coalesce(p_reason,''))) not between 8 and 500 then raise exception 'DOCUMENT_DELETE_REASON_REQUIRED' using errcode='22023';end if;
 -- Serialize retries before examining the immutable action identity.
 perform pg_advisory_xact_lock(hashtextextended(p_action_id::text,0));
 select * into v_op from document_retirement_private.operations where id=p_action_id;
 if found then
  if v_op.affiliate_id<>p_affiliate_id or v_op.document_id<>p_document_id or v_op.actor_auth_user_id<>auth.uid() or v_op.fingerprint is distinct from p_fingerprint or v_op.reason is distinct from btrim(p_reason) then raise exception 'DOCUMENT_DELETE_RETRY_MISMATCH' using errcode='42501';end if;
  return jsonb_build_object('operation_id',v_op.id,'status',case when v_op.completed_at is null then 'PENDING_STORAGE' else 'COMPLETE' end);
 end if;
 select array_agg(document_id),array_agg(distinct asset_id) filter(where asset_id is not null) into ids,assets from document_retirement_private.scope(p_affiliate_id,p_document_id);
 perform 1 from public.affiliate_documents where id=any(ids) order by id for update;
 perform 1 from public.private_assets where id=any(assets) order by id for update;
 report:=public.preview_admin_affiliate_document_delete(p_affiliate_id,p_document_id);
 if report->>'fingerprint' is distinct from p_fingerprint then raise exception 'DOCUMENT_DELETE_PREVIEW_STALE';end if;
 if (report->>'blocked')::boolean then raise exception 'DOCUMENT_SHARED_REFERENCE';end if;
 insert into document_retirement_private.operations(id,affiliate_id,document_id,actor_auth_user_id,effective_affiliate_id,reason,fingerprint)
 values(p_action_id,p_affiliate_id,p_document_id,auth.uid(),public.get_effective_affiliate_id(),btrim(p_reason),p_fingerprint);
 insert into document_retirement_private.documents(document_id,operation_id,affiliate_file_id,asset_id)
 select document_id,p_action_id,affiliate_file_id,asset_id from document_retirement_private.scope(p_affiliate_id,p_document_id);
 insert into document_retirement_private.assets(asset_id,operation_id,storage_bucket,original_path,quarantine_path,original_sha256,original_status)
 select pa.id,p_action_id,pa.storage_bucket,pa.storage_path,'retired-documents/'||p_action_id::text||'/'||pa.id::text,pa.content_sha256,pa.status
 from public.private_assets pa where pa.id=any(assets);
 -- Preserve the original hash privately while allowing the same bytes to be
 -- uploaded under their correct owner with a new, independent object/path.
 update public.private_assets set status='DISABLED',content_sha256=null where id=any(assets);
 insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
 values(auth.uid(),p_affiliate_id,'affiliate_documents','ADMIN_DOCUMENT_DELETE',p_document_id,
 jsonb_build_object('operation_id',p_action_id,'reason',btrim(p_reason),'document_ids',ids,'effective_affiliate_id',public.get_effective_affiliate_id(),'storage_state','PENDING_STORAGE'));
 return jsonb_build_object('operation_id',p_action_id,'status','PENDING_STORAGE');
end $function$

CREATE OR REPLACE FUNCTION document_retirement_private.guard_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v uuid;kind text;begin
 for i in 0..tg_nargs-1 by 2 loop
  v:=nullif(to_jsonb(new)->>tg_argv[i],'')::uuid;kind:=tg_argv[i+1];
  if v is null then continue;end if;
  if tg_op='UPDATE' and tg_argv[i]<>'id' and (to_jsonb(old)->>tg_argv[i]) is not distinct from (to_jsonb(new)->>tg_argv[i]) then continue;end if;
  if kind='asset' then
   perform 1 from public.private_assets where id=v for key share;
   if not public.affiliate_document_asset_is_active(v) then raise exception 'DOCUMENT_RETIRED' using errcode='42501';end if;
  elsif kind='file' then
   perform 1 from public.affiliate_files where id=v for key share;
   if not public.affiliate_document_file_is_active(v) then raise exception 'DOCUMENT_RETIRED' using errcode='42501';end if;
  else
   perform 1 from public.affiliate_documents where id=v for key share;
   if not public.affiliate_document_is_active(v) then raise exception 'DOCUMENT_RETIRED' using errcode='42501';end if;
  end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.register_affiliate_document(p_document_type_id uuid, p_storage_path text, p_mime_type text, p_file_size bigint, p_sha256 text, p_source text)
 RETURNS affiliate_documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_affiliate uuid;v_type public.document_types%rowtype;v_asset public.private_assets%rowtype;v_doc public.affiliate_documents%rowtype;v_replaced uuid;v_path text:=btrim(p_storage_path);
begin
  v_affiliate:=public.get_effective_affiliate_id();
  if auth.uid() is null or v_affiliate is null then raise exception 'AFFILIATE_REQUIRED' using errcode='42501'; end if;
  select * into v_type from public.document_types where id=p_document_type_id and enabled;
  if v_type.id is null then raise exception 'DOCUMENT_TYPE_UNAVAILABLE' using errcode='22023'; end if;
  if upper(coalesce(p_source,'')) not in('CAMERA','FILE')
    or (upper(p_source)='CAMERA' and not v_type.camera_allowed)
    or (upper(p_source)='FILE' and not v_type.file_upload_allowed)
    or (upper(p_source)='CAMERA' and p_mime_type not like 'image/%')
    or not(p_mime_type=any(v_type.accepted_mime_types)) or p_file_size<1 or p_file_size>v_type.max_file_size_bytes or upper(p_sha256)!~'^[A-F0-9]{64}$' then raise exception 'INVALID_DOCUMENT_FILE' using errcode='22023'; end if;
  if v_path!~('^affiliate-documents/'||v_affiliate::text||'/[A-Za-z0-9._-]+$') then raise exception 'INVALID_STORAGE_PATH' using errcode='22023'; end if;
  if not exists(select 1 from storage.objects where bucket_id='private-assets' and name=v_path and owner_id=auth.uid()::text) then raise exception 'UPLOAD_NOT_FOUND' using errcode='22023'; end if;
  select d.id into v_replaced from document_retirement_private.active_documents d where d.affiliate_id=v_affiliate and d.document_type_id=p_document_type_id order by d.created_at desc,d.id desc limit 1;
  select * into v_asset from public.private_assets where content_sha256=upper(p_sha256);
  if v_asset.id is null then insert into public.private_assets(asset_key,asset_type,title,storage_bucket,storage_path,mime_type,file_size,content_sha256)
